/**
 * Client for communicating with Roverfox Manager
 */

import axios, { type AxiosInstance } from 'axios';

import type {
  BrowserType,
  Platform,
  ServerAssignment,
  ServerAssignmentOptions,
} from './types.js';

export class ManagerClient {
  private manager: AxiosInstance;
  private debug: boolean;

  constructor(apiKey: string, managerUrl?: string, debug: boolean = false) {
    this.manager = axios.create({
      baseURL:
        managerUrl ||
        process.env.ROVERFOX_MANAGER_URL ||
        'https://manager.roverfox.net',
      headers: {
        Authorization: `Bearer ${apiKey}`,
      },
    });
    this.debug = debug;
  }

  /**
   * Gets server assignment from manager
   */
  async getServerAssignment(
    options?: ServerAssignmentOptions
  ): Promise<ServerAssignment> {
    const opts = {
      // Default options
      platform: 'mac',
      // User provided options
      ...options,
    };
    try {
      const params = new URLSearchParams();
      if (opts.browserId) params.append('browserId', opts.browserId);
      if (opts.platform) params.append('platform', opts.platform);
      if (opts.browserType) params.append('browserType', opts.browserType);

      const { data: assignment } = await this.manager.get(
        '/api/assign-server',
        { params }
      );
      if (this.debug)
        console.log(`[client] Assigned to server ${assignment.serverIp}`);
      return assignment;
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to get server assignment:', error);
      throw error;
    }
  }
  /**
   * Assigns the least-used Firefox fingerprint from the pool.
   * Returns fingerprint data mapped to ProfileStorageData fields.
   */
  async assignFingerprint(
    platform: Platform = 'mac',
    browserType: BrowserType = 'camoufox'
  ): Promise<{
    fingerprintId: string;
    userAgent: string | null;
    navigatorPlatform: string;
    navigatorOscpu: string;
    hardwareConcurrency: number;
    webglVendor: string | null;
    webglRenderer: string | null;
    screenDimensions: { width: number; height: number; colorDepth: number };
    devicePixelRatio: number;
    fontList: string[];
    speechVoices: string[];
  }> {
    try {
      const { data } = await this.manager.post('/api/fingerprints/assign', {
        platform,
        browserType,
      });
      return data;
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to assign fingerprint:', error);
      throw error;
    }
  }

  /**
   * Fetches a specific fingerprint by ID (for backfill of missing fields).
   * Returns the same format as assignFingerprint() but does NOT increment times_assigned.
   */
  async getFingerprint(fingerprintId: string): Promise<{
    fingerprintId: string;
    userAgent: string | null;
    navigatorPlatform: string;
    navigatorOscpu: string;
    hardwareConcurrency: number;
    webglVendor: string | null;
    webglRenderer: string | null;
    screenDimensions: { width: number; height: number; colorDepth: number };
    devicePixelRatio: number;
    fontList: string[];
    speechVoices: string[];
  }> {
    try {
      const { data } = await this.manager.get(
        `/api/fingerprints/${fingerprintId}`
      );
      return data;
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to get fingerprint:', error);
      throw error;
    }
  }

  /**
   * Selects a geo-matched proxy for a browser profile.
   * Manager handles the DB lookup, health check, and reservation.
   */
  async selectProxy(params: {
    browserId?: string;
    geoState?: string;
    latitude?: number;
    longitude?: number;
    service?: string;
  }): Promise<{
    proxyId: number;
    proxyUrl: string;
    exitIp: string | null;
    geoState: string | null;
  }> {
    try {
      const { data } = await this.manager.post('/api/proxies/select', params);
      // Normalize: pool-based returns { proxyId, proxyUrl, exitIp, geoState },
      // service-based returns ProxyCredentials { proxyUrl, proxyId?, geoState?, ... }
      if (!data.proxyUrl) {
        throw new Error(data.error || 'No proxyUrl in Manager response');
      }
      return {
        proxyId: data.proxyId ?? 0,
        proxyUrl: data.proxyUrl,
        exitIp: data.exitIp ?? null,
        geoState: data.geoState ?? null,
      };
    } catch (error) {
      if (this.debug) console.error('[client] Failed to select proxy:', error);
      throw error;
    }
  }

  /**
   * Releases a proxy back to the pool after session ends.
   */
  async releaseProxy(proxyId: number, rotate: boolean = true): Promise<void> {
    try {
      await this.manager.post('/api/proxies/release', { proxyId, rotate });
    } catch (error) {
      if (this.debug) console.error('[client] Failed to release proxy:', error);
      // Non-critical: don't throw — stale cleanup will handle it
    }
  }

  /**
   * Assigns a geo state to a profile proportionally based on proxy availability.
   */
  async assignGeo(
    browserId: string
  ): Promise<{ geoState: string; latitude: number; longitude: number }> {
    try {
      const { data } = await this.manager.post('/api/proxies/assign-geo', {
        browserId,
      });
      return data;
    } catch (error) {
      if (this.debug) console.error('[client] Failed to assign geo:', error);
      throw error;
    }
  }

  /**
   * Lists all profiles via manager
   */
  async listProfiles(): Promise<{ browser_id: string; data: any }[]> {
    try {
      const { data } = await this.manager.get('/api/profiles');
      return data;
    } catch (error) {
      if (this.debug) console.error('[client] Failed to list profiles:', error);
      throw error;
    }
  }

  /**
   * Gets profile and proxy data from manager
   */
  async getProfile(browserId: string): Promise<any> {
    try {
      const { data } = await this.manager.get(`/api/profiles/${browserId}`);
      return data;
    } catch (error) {
      if (this.debug) console.error('[client] Failed to get profile:', error);
      throw error;
    }
  }

  /**
   * Creates a new profile via manager
   */
  async createProfile(
    browserId: string,
    profileData: any,
    platform?: Platform,
    browserType?: BrowserType
  ): Promise<void> {
    try {
      await this.manager.post('/api/profiles', {
        browserId,
        profileData,
        platform,
        browserType,
      });
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to create profile:', error);
      throw error;
    }
  }

  /**
   * Updates profile data via manager
   */
  async updateProfileData(browserId: string, profileData: any): Promise<void> {
    try {
      await this.manager.patch(`/api/profiles/${browserId}`, {
        profileData,
      });
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to update profile data:', error);
      throw error;
    }
  }

  /**
   * Deletes a profile via manager
   */
  async deleteProfile(browserId: string): Promise<void> {
    try {
      await this.manager.delete(`/api/profiles/${browserId}`);
    } catch (error) {
      if (this.debug)
        console.error('[client] Failed to delete profile:', error);
      throw error;
    }
  }

  /**
   * Updates storage state via manager
   */
  async updateStorage(browserId: string, storageData: any): Promise<void> {
    try {
      await this.manager.post(
        `/api/profiles/${browserId}/storage`,
        storageData
      );
    } catch (error) {
      // Silently ignore storage update errors as they aren't critical
      if (this.debug)
        console.error('[client] Failed to update storage:', error);
    }
  }

  /**
   * Logs an action audit via manager
   */
  async logAudit(
    browserId: string,
    actionType: string,
    metadata: any
  ): Promise<void> {
    try {
      await this.manager.post('/api/audit', {
        browserId,
        actionType,
        metadata,
      });
    } catch (error) {
      if (this.debug) console.error('[client] Failed to log audit:', error);
    }
  }

  /**
   * Logs data usage via manager
   */
  async logUsage(
    browserId: string,
    start: string,
    end: string,
    bytes: number,
    isOneTime: boolean = false,
    serverId?: string
  ): Promise<void> {
    try {
      await this.manager.post('/api/usage', {
        browserId,
        start,
        end,
        bytes,
        isOneTime,
        serverId,
      });
    } catch (error) {
      if (this.debug) console.error('[client] Failed to log usage:', error);
    }
  }
}
